mapper.select:
select board.b_no, b_u_id, r_name, b_title, b_like, b_scrap, B_CREATED_DATE from board, region, (select b_no, count(*) as b_like From BOARD, Board_like where b_no = B_L_B_NO group by b_no) board_like, (select b_no, count(*) as b_scrap From BOARD, Board_scrap where b_no = B_S_B_NO group by b_no) board_scrap where B_REGION_NO = r_no and board.b_no = board_like.B_NO(+) and board.b_no = board_scrap.B_NO(+)
AND b_region_no = #{place}
AND b_cg_no = #{category}
AND LOWER(board.b_title) LIKE '%' || LOWER(#{keyword}) || '%'
ORDER BY b_created_date DESC
